before:
// ponytail: try/catch guards against pi-web theme proxy throwing before initTheme
let theme;
try { theme = c.ui.theme; if (!theme?.fg) return; } catch { return; }
if (currentMode === "off") {
  c.ui.setStatus("ponytail", undefined);
  return;
}
const levelIcons = { lite: "🌿", full: "⚡", ultra: "🔥" };
const icon = levelIcons[currentMode] || "";
const label = currentMode.toUpperCase();
const indicator = isActive ? theme.fg("accent", "●") : theme.fg("dim", "○");
c.ui.setStatus("ponytail", indicator + " 🐴 " + theme.fg("muted", "ponytail: ") + theme.fg("text", icon + " " + label));

after:
if (currentMode === "off") {
  c.ui.setStatus("ponytail", undefined);
  return;
}
// RPC does not initialize the interactive theme; keep status usable as plain text.
let fg = (_color, text) => text;
try {
  const theme = c.ui.theme;
  if (typeof theme?.fg === "function") fg = (color, text) => theme.fg(color, text);
} catch {}
const levelIcons = { lite: "🌿", full: "⚡", ultra: "🔥" };
const icon = levelIcons[currentMode] || "";
const label = currentMode.toUpperCase();
const indicator = fg(isActive ? "accent" : "dim", isActive ? "●" : "○");
c.ui.setStatus("ponytail", indicator + " 🐴 " + fg("muted", "ponytail: ") + fg("text", icon + " " + label));
